-- OxiLedger schema for SQLite.
--
-- Mirrors the Postgres schema, with these differences in how values are stored:
--   * IDs are hyphenated UUID text, generated by the application.
--   * Timestamps are UTC text with microseconds, like 2026-01-31T12:00:00.000000Z.
--   * Dates are text, like 2026-01-31.
--   * Money is an integer count of ten-thousandths of a unit, so 12.34 is 123400.
--   * Booleans are 0 or 1, and JSON is text.

CREATE TABLE users (
    id            TEXT PRIMARY KEY NOT NULL,
    username      TEXT NOT NULL UNIQUE,
    email         TEXT NOT NULL UNIQUE,
    password_hash TEXT,                      -- NULL for OIDC-only users
    oidc_provider TEXT,
    oidc_subject  TEXT,
    preferences   TEXT NOT NULL DEFAULT '{}',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    UNIQUE (oidc_provider, oidc_subject)
) STRICT;

CREATE TABLE sessions (
    id         TEXT PRIMARY KEY NOT NULL,
    user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token      TEXT NOT NULL UNIQUE,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
) STRICT;

CREATE INDEX idx_sessions_user ON sessions(user_id);

-- Short-lived PKCE + CSRF state rows created at the start of each OIDC flow.
CREATE TABLE oidc_states (
    id            TEXT PRIMARY KEY NOT NULL,
    provider_id   TEXT NOT NULL,
    csrf_token    TEXT NOT NULL UNIQUE,
    pkce_verifier TEXT NOT NULL,
    nonce         TEXT NOT NULL,
    expires_at    TEXT NOT NULL,
    created_at    TEXT NOT NULL
) STRICT;

CREATE INDEX idx_oidc_states_expires ON oidc_states(expires_at);

-- Chart of accounts
CREATE TABLE accounts (
    id             TEXT PRIMARY KEY NOT NULL,
    user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name           TEXT NOT NULL,
    code           TEXT,
    account_type   TEXT NOT NULL
        CHECK (account_type IN ('Asset', 'Liability', 'Equity', 'Revenue', 'Expense')),
    normal_balance TEXT NOT NULL CHECK (normal_balance IN ('Debit', 'Credit')),
    description    TEXT,
    is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (user_id, code)
) STRICT;

CREATE INDEX idx_accounts_user ON accounts(user_id);

-- Transaction headers
CREATE TABLE transactions (
    id          TEXT PRIMARY KEY NOT NULL,
    user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    date        TEXT NOT NULL,
    description TEXT NOT NULL,
    reference   TEXT,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
) STRICT;

CREATE INDEX idx_transactions_user_date ON transactions(user_id, date);

-- Journal entry lines (debits/credits per transaction).
-- Balanced transactions are enforced at the application level (sum debits == sum credits).
CREATE TABLE journal_entries (
    id                  TEXT PRIMARY KEY NOT NULL,
    transaction_id      TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    account_id          TEXT NOT NULL REFERENCES accounts(id),
    entry_type          TEXT NOT NULL CHECK (entry_type IN ('Debit', 'Credit')),
    amount              INTEGER NOT NULL CHECK (amount > 0),
    memo                TEXT,
    -- The bank transaction this entry was created from, if any.
    bank_transaction_id TEXT REFERENCES bank_transactions(id) ON DELETE SET NULL,
    created_at          TEXT NOT NULL
) STRICT;

CREATE INDEX idx_journal_entries_transaction ON journal_entries(transaction_id);
CREATE INDEX idx_journal_entries_account ON journal_entries(account_id);
CREATE INDEX idx_journal_entries_bank_txn
    ON journal_entries(bank_transaction_id)
    WHERE bank_transaction_id IS NOT NULL;

-- A bank connection represents a single authorization session with a provider
-- (e.g. one Enable Banking session covering one or more bank accounts).
CREATE TABLE bank_connections (
    id                     TEXT PRIMARY KEY NOT NULL,
    user_id                TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider_id            TEXT NOT NULL,
    provider_session_id    TEXT NOT NULL,
    aspsp_name             TEXT,
    aspsp_country          TEXT,
    access_valid_until     TEXT,
    provider_accounts_json TEXT,
    -- The manual account the connection was started from, if any.
    source_bank_account_id TEXT REFERENCES bank_accounts(id) ON DELETE SET NULL,
    created_at             TEXT NOT NULL
) STRICT;

CREATE INDEX idx_bank_connections_user ON bank_connections(user_id);

-- A specific bank account, linked to an internal ledger account.
-- bank_connection_id and provider_account_uid are NULL for manual (non-synced) accounts.
CREATE TABLE bank_accounts (
    id                   TEXT PRIMARY KEY NOT NULL,
    user_id              TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    bank_connection_id   TEXT REFERENCES bank_connections(id) ON DELETE CASCADE,
    internal_account_id  TEXT REFERENCES accounts(id),
    provider_account_uid TEXT,
    iban                 TEXT,
    name                 TEXT,
    currency             TEXT NOT NULL DEFAULT 'EUR',
    is_manual            INTEGER NOT NULL DEFAULT 0 CHECK (is_manual IN (0, 1)),
    balance              INTEGER,            -- last known bank balance from sync
    last_synced_at       TEXT,
    created_at           TEXT NOT NULL
) STRICT;

CREATE INDEX idx_bank_accounts_user ON bank_accounts(user_id);
CREATE INDEX idx_bank_accounts_internal_account
    ON bank_accounts(internal_account_id)
    WHERE internal_account_id IS NOT NULL;

-- Provider uniqueness only applies to connected (non-manual) accounts.
CREATE UNIQUE INDEX idx_bank_accounts_provider_uid
    ON bank_accounts(bank_connection_id, provider_account_uid)
    WHERE bank_connection_id IS NOT NULL AND provider_account_uid IS NOT NULL;

-- Imported (staged) bank transactions waiting to be linked to a ledger transaction.
-- amount > 0 means money coming into the account; amount < 0 means money leaving it.
CREATE TABLE bank_transactions (
    id                      TEXT PRIMARY KEY NOT NULL,
    bank_account_id         TEXT NOT NULL REFERENCES bank_accounts(id) ON DELETE CASCADE,
    user_id                 TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    external_id             TEXT NOT NULL,
    date                    TEXT NOT NULL,
    amount                  INTEGER NOT NULL,
    currency                TEXT NOT NULL,
    description             TEXT NOT NULL,
    reference               TEXT,
    status                  TEXT NOT NULL DEFAULT 'pending', -- pending | linked | dismissed
    linked_journal_entry_id TEXT REFERENCES journal_entries(id) ON DELETE SET NULL,
    imported_at             TEXT NOT NULL,
    UNIQUE (bank_account_id, external_id)                    -- idempotent import
) STRICT;

CREATE INDEX idx_bank_transactions_user ON bank_transactions(user_id);
CREATE INDEX idx_bank_transactions_status ON bank_transactions(bank_account_id, status);
CREATE INDEX idx_bank_transactions_linked_entry
    ON bank_transactions(linked_journal_entry_id)
    WHERE linked_journal_entry_id IS NOT NULL;

-- Temporary state records for in-flight bank authorization flows.
-- Consumed (deleted) by the callback handler after use.
CREATE TABLE bank_auth_states (
    id                     TEXT PRIMARY KEY NOT NULL,
    user_id                TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider_id            TEXT NOT NULL,
    state                  TEXT NOT NULL UNIQUE,
    aspsp_name             TEXT,
    aspsp_country          TEXT,
    provider_reference     TEXT,
    source_bank_account_id TEXT REFERENCES bank_accounts(id) ON DELETE SET NULL,
    expires_at             TEXT NOT NULL,
    created_at             TEXT NOT NULL
) STRICT;

CREATE INDEX idx_bank_auth_states_expires ON bank_auth_states(expires_at);
